<?php
require_once __DIR__.'/daily_point_whatsapp_template_test.php';
require_once __DIR__.'/../services/DailyPointWhatsAppTemplateMonitor.php';
$state=['sid'=>$sid,'status'=>'approved','reason'=>'','failures'=>0,'activated_at'=>100];
$failed=DailyPointWhatsAppTemplateMonitor::observation($state,null,'Erreur HTTP 503',1000);
check($failed['status']==='approved'&&$failed['activated_at']===100,'Une panne API ne doit pas modifier le statut ou le modèle actif.');
check($failed['next_check']===1300&&$failed['failures']===1,'Premier délai de reprise incorrect.');
$failed=DailyPointWhatsAppTemplateMonitor::observation($failed,null,'Erreur HTTP 503',1300);
check($failed['next_check']===1900,'Le délai doit augmenter après deux pannes.');
for($i=0;$i<15;$i++)$failed=DailyPointWhatsAppTemplateMonitor::observation($failed,null,'Erreur HTTP 503',2000);
check($failed['next_check']===23600,'Le délai doit rester borné à six heures.');
$rejected=DailyPointWhatsAppTemplateMonitor::observation($failed,['status'=>'rejected','category'=>'UTILITY','reason'=>'2388024 : French content exists'],null,3000);
check($rejected['status']==='rejected'&&$rejected['reason']!=='','Le rejet et son motif doivent être récupérables.');
check($rejected['failures']===0&&$rejected['error']===''&&$rejected['last_success']===3000,'Une reprise doit effacer l’erreur réseau.');
$pending=DailyPointWhatsAppTemplateMonitor::observation($state,['status'=>'pending','category'=>'UTILITY','reason'=>''],null,4000);
check($pending['next_check']===4300,'Les demandes en attente sont contrôlées toutes les cinq minutes.');
$approved=DailyPointWhatsAppTemplateMonitor::observation($pending,['status'=>'approved','category'=>'UTILITY','reason'=>''],null,5000);
check($approved['next_check']===8600,'Un modèle approuvé reste surveillé toutes les heures.');
$api->responses=[['sid'=>$sid],new RuntimeException('Soumission refusée')];$savedSid='';
rejects(function()use($api,&$savedSid){$api->createAndSubmit('finea_test',DailyPointWhatsAppTemplateService::BODY,function($sid)use(&$savedSid){$savedSid=$sid;});},$sid);
check($savedSid===$sid,'Le SID doit être enregistré avant la soumission, même si celle-ci échoue.');
$custom=str_replace('Merci.','Merci pour votre validation.',DailyPointWhatsAppTemplateService::BODY);
$definition=DailyPointWhatsAppTemplateService::definition('finea_test',$custom);
$api->responses=[$definition,['whatsapp'=>['status'=>'approved']]];$api->assertApproved($sid,$custom);
rejects(fn()=>DailyPointWhatsAppTemplateService::definition('finea_test',$custom.' {{7}}'), 'variables');
rejects(fn()=>DailyPointWhatsAppTemplateService::definition('finea_test',$custom.' {{oops'), 'mal formée');
$secret=str_repeat('c',64);$diagnostic=DailyPointWhatsAppTemplateService::safeDiagnostic('token=abc123 '.$secret.' <b>refusé</b>');
check(!str_contains($diagnostic,'abc123')&&!str_contains($diagnostic,$secret)&&!str_contains($diagnostic,'<b>'),'Les diagnostics ne doivent contenir ni jeton ni HTML.');
echo "OK : suivi des rejets, reprise réseau bornée, conservation du statut, SID après échec, texte corrigé et diagnostics.\n";
